public readonly record struct ParseResult(bool Ok, string? Error, CsvRow? Row);

public static ParseResult TryParseRow(string line)
{
    if (string.IsNullOrWhiteSpace(line))
        return new(false, "empty line", null);
    // expected failure — no stack walk
    return new(true, null, new CsvRow(line));
}

// Reserve throw for programmer bugs or unrecoverable I/O:
public static CsvRow ParseOrThrow(string line) =>
    TryParseRow(line) is { Ok: true, Row: { } row }
        ? row
        : throw new InvalidOperationException("invariant broken");
